INSERT INTO feature VALUES('transport','identity','Transport','identity-types','implemented','notable',NULL,'`Path.walk(P, p, v)` moves an element along an identification through a family; a record moves field by field under its labels, and a suspension whose run performs no effect runs, forced, and its result moves on. A value declared as a transport is computed the first time a run reads it, and every later read is that answer; a transport written where a value is read — a call''s argument, a tuple''s component, a constructor''s field, a case''s scrutinee — runs before what reads it.','core-checker core-nbe core-term kernel-core core-sequent runtime-emitter surface-lowering','corpus/model/identity/transport-path.gandr corpus/model/identity/transport-list.gandr corpus/model/identity/flow-large.gandr corpus/model/modules/model-manifest-type.gandr corpus/model/data/one-shape-families.gandr corpus/model/identity/a-transport-of-a-call-s-result.gandr corpus/model/identity/transports-in-a-variable-family.gandr corpus/model/identity/transport-through-a-named-family.gandr','corpus/ledger/features/transport.gandr',NULL);
